globalThis.BAGGLE_SUPABASE_URL = "https://wndqubtncxtbninmojpx.supabase.co";
globalThis.BAGGLE_SUPABASE_ANON_KEY = "sb_publishable_vfYfD-LtUoJEbjkvhEdckg_PbAEr-PJ";
;
const resetSupabase = supabase.createClient(
globalThis.BAGGLE_SUPABASE_URL,
globalThis.BAGGLE_SUPABASE_ANON_KEY,
{
auth: {
storageKey: "baggle_dashboard_session_v1",
persistSession: true,
autoRefreshToken: true
}
}
);
const resetTagline = document.getElementById("resetTagline");
const resetForm = document.getElementById("resetForm");
const resetInvalid = document.getElementById("resetInvalid");
const resetDone = document.getElementById("resetDone");
const newPasswordInput = document.getElementById("newPassword");
const confirmPasswordInput = document.getElementById("confirmPassword");
const resetError = document.getElementById("resetError");
const resetNotice = document.getElementById("resetNotice");
const resetSubmitBtn = document.getElementById("resetSubmitBtn");
function showInvalid() {
resetTagline.textContent = "Reset your password";
resetForm.hidden = true;
resetDone.hidden = true;
resetInvalid.hidden = false;
}
function showForm() {
resetTagline.textContent = "Choose a new password for your account.";
resetInvalid.hidden = true;
resetDone.hidden = true;
resetForm.hidden = false;
}
async function init() {
const params = new URLSearchParams(window.location.search);
const code = params.get("code");
if (code) {
const { error } = await resetSupabase.auth.exchangeCodeForSession(code);
if (error) {
console.error("Failed to exchange recovery code", error);
showInvalid();
return;
}
showForm();
return;
}
const { data } = await resetSupabase.auth.getSession();
if (data.session) {
showForm();
} else {
showInvalid();
}
}
resetSubmitBtn.addEventListener("click", async () => {
const password = newPasswordInput.value;
const confirmValue = confirmPasswordInput.value;
resetError.textContent = "";
resetNotice.textContent = "";
if (!password || password.length < 6) {
resetError.textContent = "Password must be at least 6 characters.";
return;
}
if (password !== confirmValue) {
resetError.textContent = "Those passwords don't match.";
return;
}
resetSubmitBtn.disabled = true;
const originalLabel = resetSubmitBtn.textContent;
resetSubmitBtn.textContent = "Saving…";
try {
const { error } = await resetSupabase.auth.updateUser({ password });
if (error) {
resetError.textContent = error.message;
return;
}
resetForm.hidden = true;
resetDone.hidden = false;
} catch (err) {
console.error(err);
resetError.textContent = "Something went wrong reaching Baggle's servers. Check your connection and try again.";
} finally {
resetSubmitBtn.disabled = false;
resetSubmitBtn.textContent = originalLabel;
}
});
confirmPasswordInput.addEventListener("keydown", (e) => {
if (e.key === "Enter") resetSubmitBtn.click();
});
init();
